SELECT status, COUNT(*) AS cnt, SORT_ARRAY(COLLECT_SET(status)) AS status_list, COUNT(CASE WHEN status = 'COMPLETED' THEN 1 END) AS completed_count FROM orders WHERE YEAR(order_date) >= 2024 AND (store_id IN (22, 31) OR order_date BETWEEN '2023-11-01' AND '2025-09-30') GROUP BY status ORDER BY cnt DESC;
